import{_ as r}from"./chunks/prontera-church.uydloSKv.js";import{c as e,Q as t,j as o,m as i}from"./chunks/framework.BPKcPtvA.js";const b=JSON.parse('{"title":"RO3 新手 FAQ - 常见问题解答","description":"仙境传说3新手入门必看，从职业选择、练级技巧到经济系统，18个常见问题全面解答。","frontmatter":{"title":"RO3 新手 FAQ - 常见问题解答","description":"仙境传说3新手入门必看，从职业选择、练级技巧到经济系统，18个常见问题全面解答。","lastUpdated":true},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1780230058000}'),l={name:"guide/faq.md"};function h(n,a,d,s,q,c){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="新手-faq" tabindex="-1">新手 FAQ <a class="header-anchor" href="#新手-faq" aria-label="Permalink to &quot;新手 FAQ&quot;">​</a></h1><p><img src="'+r+'" alt="RO3 大教堂"></p><h2 id="基础问题" tabindex="-1">基础问题 <a class="header-anchor" href="#基础问题" aria-label="Permalink to &quot;基础问题&quot;">​</a></h2><h3 id="q-ro3-什么时候上线" tabindex="-1">Q：RO3 什么时候上线？ <a class="header-anchor" href="#q-ro3-什么时候上线" aria-label="Permalink to &quot;Q：RO3 什么时候上线？&quot;">​</a></h3><p>2026 年全球同步上线，目前仍在开发中。中国大陆已获得版号（ISBN 978-7-498-15873-4），由上海热血网络科技运营。</p><h3 id="q-ro3-是手机游戏还是-pc-游戏" tabindex="-1">Q：RO3 是手机游戏还是 PC 游戏？ <a class="header-anchor" href="#q-ro3-是手机游戏还是-pc-游戏" aria-label="Permalink to &quot;Q：RO3 是手机游戏还是 PC 游戏？&quot;">​</a></h3><p>跨平台游戏，同时支持 PC、iOS、Android，数据互通。PC 端体验更完整，手机端适合日常挂机。</p><h3 id="q-需要加速器吗" tabindex="-1">Q：需要加速器吗？ <a class="header-anchor" href="#q-需要加速器吗" aria-label="Permalink to &quot;Q：需要加速器吗？&quot;">​</a></h3><p>全球服可能不需要，但连接海外服务器时延迟可能较高。建议备一个加速器。</p><h3 id="q-ro3-和-ro1-ro-重生有什么区别" tabindex="-1">Q：RO3 和 RO1/RO 重生有什么区别？ <a class="header-anchor" href="#q-ro3-和-ro1-ro-重生有什么区别" aria-label="Permalink to &quot;Q：RO3 和 RO1/RO 重生有什么区别？&quot;">​</a></h3><ul><li><strong>RO1（PC 端）</strong>：2002 年原版 2D 游戏，仍在运营</li><li><strong>RO 重生（手机版）</strong>：重制版手游，有较大改动</li><li><strong>RO3</strong>：系列正统续作，全新 3D 引擎，保留经典玩法 + 全面升级</li></ul><h2 id="职业相关" tabindex="-1">职业相关 <a class="header-anchor" href="#职业相关" aria-label="Permalink to &quot;职业相关&quot;">​</a></h2><h3 id="q-零氪玩家推荐什么职业" tabindex="-1">Q：零氪玩家推荐什么职业？ <a class="header-anchor" href="#q-零氪玩家推荐什么职业" aria-label="Permalink to &quot;Q：零氪玩家推荐什么职业？&quot;">​</a></h3><p><strong>剑士</strong> &gt; <strong>牧师</strong> &gt; <strong>弓箭手</strong>。剑士能抗能打不需要好装备，牧师组队永远是抢手货。</p><h3 id="q-哪个职业练级最快" tabindex="-1">Q：哪个职业练级最快？ <a class="header-anchor" href="#q-哪个职业练级最快" aria-label="Permalink to &quot;Q：哪个职业练级最快？&quot;">​</a></h3><p><strong>法师</strong>（群怪效率最高）、<strong>剑士</strong>（续航最强）。</p><h3 id="q-哪个职业最赚钱" tabindex="-1">Q：哪个职业最赚钱？ <a class="header-anchor" href="#q-哪个职业最赚钱" aria-label="Permalink to &quot;Q：哪个职业最赚钱？&quot;">​</a></h3><p><strong>刺客</strong>（打材料效率第一）&gt; <strong>商人</strong>（制作出售装备）。</p><p>详细对比见 <a href="/guide/job-pick.html">职业选择推荐</a>。</p><h2 id="练级相关" tabindex="-1">练级相关 <a class="header-anchor" href="#练级相关" aria-label="Permalink to &quot;练级相关&quot;">​</a></h2><h3 id="q-1-99-级要多久" tabindex="-1">Q：1-99 级要多久？ <a class="header-anchor" href="#q-1-99-级要多久" aria-label="Permalink to &quot;Q：1-99 级要多久？&quot;">​</a></h3><p>如果有时间玩，约 2-3 周。如果每天只挂机，约 1-2 个月。</p><h3 id="q-可以自动挂机吗" tabindex="-1">Q：可以自动挂机吗？ <a class="header-anchor" href="#q-可以自动挂机吗" aria-label="Permalink to &quot;Q：可以自动挂机吗？&quot;">​</a></h3><p>可以。RO3 内置自动战斗，效率约手动的 70%-80%，日常练级够用。</p><h3 id="q-多少级开始组队" tabindex="-1">Q：多少级开始组队？ <a class="header-anchor" href="#q-多少级开始组队" aria-label="Permalink to &quot;Q：多少级开始组队？&quot;">​</a></h3><p>30 级后建议组队，高级副本和 BOSS 必须组队。</p><h3 id="q-转职后可以洗点吗" tabindex="-1">Q：转职后可以洗点吗？ <a class="header-anchor" href="#q-转职后可以洗点吗" aria-label="Permalink to &quot;Q：转职后可以洗点吗？&quot;">​</a></h3><p>可以，游戏内提供洗点方式（可能需要消耗游戏币或道具）。</p><h2 id="经济相关" tabindex="-1">经济相关 <a class="header-anchor" href="#经济相关" aria-label="Permalink to &quot;经济相关&quot;">​</a></h2><h3 id="q-平民能搬砖赚钱吗" tabindex="-1">Q：平民能搬砖赚钱吗？ <a class="header-anchor" href="#q-平民能搬砖赚钱吗" aria-label="Permalink to &quot;Q：平民能搬砖赚钱吗？&quot;">​</a></h3><p>可以。刺客或商人搬砖效率很高：</p><ul><li>刷材料出售</li><li>制作装备出售</li><li>倒买倒卖</li></ul><h3 id="q-这个游戏氪金严重吗" tabindex="-1">Q：这个游戏氪金严重吗？ <a class="header-anchor" href="#q-这个游戏氪金严重吗" aria-label="Permalink to &quot;Q：这个游戏氪金严重吗？&quot;">​</a></h3><p>官方宣传是轻氪金设计：</p><ul><li>赛季制避免数值膨胀</li><li>自由交易让平民也能获得好装备</li><li>但具体氪金程度要等上线后验证</li></ul><h3 id="q-有拍卖行-交易所吗" tabindex="-1">Q：有拍卖行/交易所吗？ <a class="header-anchor" href="#q-有拍卖行-交易所吗" aria-label="Permalink to &quot;Q：有拍卖行/交易所吗？&quot;">​</a></h3><p>有自由交易系统，经典「摆摊」回归，新增信用评分机制防工作室。</p><h2 id="技术相关" tabindex="-1">技术相关 <a class="header-anchor" href="#技术相关" aria-label="Permalink to &quot;技术相关&quot;">​</a></h2><h3 id="q-ios-和-android-数据互通吗" tabindex="-1">Q：iOS 和 Android 数据互通吗？ <a class="header-anchor" href="#q-ios-和-android-数据互通吗" aria-label="Permalink to &quot;Q：iOS 和 Android 数据互通吗？&quot;">​</a></h3><p>官方未明确说明，但作为跨平台游戏，大概率互通。</p><h3 id="q-pc-端要下载多大" tabindex="-1">Q：PC 端要下载多大？ <a class="header-anchor" href="#q-pc-端要下载多大" aria-label="Permalink to &quot;Q：PC 端要下载多大？&quot;">​</a></h3><p>预计 10-20GB（高清材质包）。</p><h3 id="q-有国服吗" tabindex="-1">Q：有国服吗？ <a class="header-anchor" href="#q-有国服吗" aria-label="Permalink to &quot;Q：有国服吗？&quot;">​</a></h3><p>有。已获得版号，由上海热血网络科技运营。国服和国际服数据不互通。</p>',44)])])}const f=e(l,[["render",h]]);export{b as __pageData,f as default};
